// src/lib/calculators/pcb/stackup-builder.ts
function solveWidth(z4, target, lo, hi) {
  if (!(z4(lo) >= target) || !(z4(hi) <= target)) return NaN;
  for (let i = 0; i < 200; i++) {
    const mid = 0.5 * (lo + hi);
    if (z4(mid) > target) lo = mid;
    else hi = mid;
    if (hi - lo <= 1e-13 * hi) break;
  }
  return 0.5 * (lo + hi);
}
function calculateStackup(inputs) {
  const {
    // layerCount is accepted but not used in current simplified model
    targetImpedance: z0,
    dielectricH1,
    dielectricH2,
    dielectricH3,
    copperWeight,
    dielectricConstant: er
  } = inputs;
  if (z0 <= 0 || er < 2 || dielectricH1 <= 0 || dielectricH2 <= 0 || dielectricH3 <= 0) {
    return {
      values: {},
      errors: ["All dielectric heights and impedance must be positive; dielectric constant ≥ 2"]
    };
  }
  const warnings = [];
  const tMm = copperWeight * 35 / 1e3;
  const totalThicknessMm = dielectricH1 + dielectricH2 + dielectricH3 + 4 * tMm;
  const zL1 = (w) => hammerstadJensen(w, dielectricH1, er, tMm).Z0;
  const traceWidthL1mm = solveWidth(zL1, z0, 1e-4 * dielectricH1, 1e3 * dielectricH1);
  const zL3 = (w) => asymmetricStripline(w, dielectricH3, dielectricH2, er, tMm).Z0;
  const bL3 = dielectricH2 + dielectricH3;
  const traceWidthL3mm = solveWidth(zL3, z0, 1e-5 * bL3, 1e3 * bL3);
  const achievedImpedanceL1 = Number.isFinite(traceWidthL1mm) ? zL1(traceWidthL1mm) : NaN;
  const achievedImpedanceL3 = Number.isFinite(traceWidthL3mm) ? zL3(traceWidthL3mm) : NaN;
  if (!Number.isFinite(traceWidthL1mm) || !Number.isFinite(traceWidthL3mm)) {
    warnings.push("The target impedance cannot be reached on this stackup");
  }
  if (totalThicknessMm < 0.5) {
    warnings.push("Very thin board: warping risk");
  }
  if (dielectricH1 < 0.08) {
    warnings.push("Prepreg too thin for standard fab");
  }
  return {
    values: {
      traceWidthL1mm,
      traceWidthL3mm,
      achievedImpedanceL1,
      achievedImpedanceL3,
      totalThicknessMm
    },
    warnings: warnings.length > 0 ? warnings : void 0
  };
}
