function calculateFilterDesigner(inputs) {
  const { responseType = 0, filterType, fc, order, impedance, qFactor: qFactor2, eSeries = 0 } = inputs;
  if (fc <= 0) {
    return { values: {}, errors: ["Cutoff frequency must be greater than zero"] };
  }
  if (impedance <= 0) {
    return { values: {}, errors: ["Impedance must be greater than zero"] };
  }
  const clampedOrder = Math.round(Math.min(10, Math.max(1, order)));
  const omega_c = 2 * Math.PI * fc;
  const isChebyshev = Math.round(responseType) === 1;
  const type = Math.round(filterType);
  const g = (isChebyshev ? CHEBYSHEV_05_G : BUTTERWORTH_G)[clampedOrder];
  const tau_ns = clampedOrder === 1 && !isChebyshev ? 1 / omega_c * 1e9 : 0;
  const { C: C7, L, bpL, bpC } = ladderValues(g, type, omega_c, impedance, qFactor2 > 0 ? qFactor2 : 1);
  let attenuation_at_2fc;
  if (isChebyshev) {
    const epsilon = Math.sqrt(Math.pow(10, CHEBYSHEV_RIPPLE_DB / 10) - 1);
    const Tn = Math.cosh(clampedOrder * Math.acosh(2));
    attenuation_at_2fc = 10 * Math.log10(1 + epsilon * epsilon * Tn * Tn);
  } else {
    attenuation_at_2fc = 10 * Math.log10(1 + Math.pow(2, 2 * clampedOrder));
  }
  let bandwidth_Hz = 0;
  let fLow_Hz = 0;
  let fHigh_Hz = 0;
  if (type === 2) {
    bandwidth_Hz = fc / qFactor2;
    fLow_Hz = fc - bandwidth_Hz / 2;
    fHigh_Hz = fc + bandwidth_Hz / 2;
  }
  let maxComponentError = 0;
  let fcShiftPercent = 0;
  const eSeriesName = `E${Math.round(eSeries)}`;
  const validSeries = ["E12", "E24", "E48", "E96"];
  if (eSeries > 0 && validSeries.includes(eSeriesName)) {
    const snapValue = (val) => {
      if (val <= 0) return val;
      const result = snapToESeries(val, eSeriesName);
      maxComponentError = Math.max(maxComponentError, Math.abs(result.error));
      return result.snapped;
    };
    for (const arr of [C7, L, bpL, bpC]) {
      for (let i = 0; i < arr.length; i++) arr[i] = snapValue(arr[i]);
    }
    fcShiftPercent = maxComponentError * 0.5;
  }
  const values = {};
  C_KEYS.forEach((k, i) => {
    values[k] = C7[i];
  });
  L_KEYS.forEach((k, i) => {
    values[k] = L[i];
  });
  BP_L_KEYS.forEach((k, i) => {
    values[k] = bpL[i];
  });
  BP_C_KEYS.forEach((k, i) => {
    values[k] = bpC[i];
  });
  const warnings = isChebyshev && clampedOrder % 2 === 0 ? [chebyshevLoadWarning(clampedOrder, type, impedance)] : [];
  return {
    ...warnings.length ? { warnings } : {},
    values: {
      C1_nF: values.C1_nF,
      L1_uH: values.L1_uH,
      C3_nF: values.C3_nF,
      L4_uH: values.L4_uH,
      C5_nF: values.C5_nF,
      L6_uH: values.L6_uH,
      C7_nF: values.C7_nF,
      L8_uH: values.L8_uH,
      C9_nF: values.C9_nF,
      L10_uH: values.L10_uH,
      bpL1_uH: values.bpL1_uH,
      bpC2_nF: values.bpC2_nF,
      bpL3_uH: values.bpL3_uH,
      bpC4_nF: values.bpC4_nF,
      bpL5_uH: values.bpL5_uH,
      bpC6_nF: values.bpC6_nF,
      bpL7_uH: values.bpL7_uH,
      bpC8_nF: values.bpC8_nF,
      bpL9_uH: values.bpL9_uH,
      bpC10_nF: values.bpC10_nF,
      tau_ns,
      attenuation_at_2fc,
      bandwidth_Hz,
      fLow_Hz,
      fHigh_Hz,
      maxComponentError,
      fcShiftPercent
    }
  };
}
