// src/lib/calculators/general/ohms-law.ts
function calculateOhmsLaw(inputs) {
  let { voltage: V, current: I, resistance: R, power: P } = inputs;
  const known = [V, I, R, P].filter((v) => v >= 0).length;
  if (known < 2) return { values: {}, errors: ["Provide at least 2 values"] };
  if (V >= 0 && I >= 0) {
    R = V / I;
    P = V * I;
  } else if (V >= 0 && R >= 0) {
    I = V / R;
    P = V * V / R;
  } else if (V >= 0 && P >= 0) {
    I = P / V;
    R = V * V / P;
  } else if (I >= 0 && R >= 0) {
    V = I * R;
    P = I * I * R;
  } else if (I >= 0 && P >= 0) {
    V = P / I;
    R = P / (I * I);
  } else if (R >= 0 && P >= 0) {
    V = Math.sqrt(P * R);
    I = Math.sqrt(P / R);
  }
  if (!isFinite(V) || !isFinite(I) || !isFinite(R) || !isFinite(P)) {
    return { values: {}, errors: ["Division by zero — ensure non-zero denominators"] };
  }
  return {
    values: {
      voltage: V,
      current: I,
      resistance: R,
      power: P
    }
  };
}
