// src/lib/calculators/general/resistor-color-code.ts
var MULTIPLIERS = {
  0: 1,
  1: 10,
  2: 100,
  3: 1e3,
  4: 1e4,
  5: 1e5,
  6: 1e6,
  7: 1e7,
  8: 1e8,
  9: 1e9,
  10: 0.1,
  11: 0.01
};
var TOLERANCES = {
  1: 1,
  2: 2,
  3: 0.05,
  4: 0.02,
  5: 0.5,
  6: 0.25,
  7: 0.1,
  8: 0.05,
  10: 5,
  11: 10
};
var COLOR_NAMES = ["black", "brown", "red", "orange", "yellow", "green", "blue", "violet", "grey", "white", "gold", "silver"];
function calculateColorCode(inputs) {
  const { band1, band2, band3, multiplier, tolerance, numBands } = inputs;
  const is5band = numBands >= 5;
  let baseValue;
  if (is5band) {
    baseValue = band1 * 100 + band2 * 10 + band3;
  } else {
    baseValue = band1 * 10 + band2;
  }
  const tol = TOLERANCES[tolerance];
  if (tol === void 0) {
    const name = COLOR_NAMES[tolerance];
    return {
      values: {},
      errors: [
        name ? `Tolerance band: ${name} has no tolerance meaning (IEC 60062)` : `Tolerance band: code ${tolerance} is not a tolerance colour (IEC 60062)`
      ]
    };
  }
  const mult = MULTIPLIERS[multiplier] ?? 1;
  const resistance = baseValue * mult;
  const minR = resistance * (1 - tol / 100);
  const maxR = resistance * (1 + tol / 100);
  return {
    values: {
      resistance,
      tolerance: tol,
      minResistance: minR,
      maxResistance: maxR
    }
  };
}
