// src/lib/calculators/emc/shielding-effectiveness.ts
function calculateShieldingEffectiveness(inputs) {
  const { frequency, thickness, conductivity, permeability } = inputs;
  const warnings = [];
  const f_Hz = frequency * 1e6;
  const mu0 = 4 * Math.PI * 1e-7;
  const mu = permeability * mu0;
  const sigma = conductivity * 1e6;
  const skinDepth_m = Math.sqrt(2 / (2 * Math.PI * f_Hz * mu * sigma));
  const skinDepth2 = skinDepth_m * 1e6;
  const t_m = thickness * 1e-3;
  const x = t_m / skinDepth_m;
  const absorptionLoss = 20 / Math.LN10 * x;
  const omega = 2 * Math.PI * f_Hz;
  const eta0 = mu0 * 299792458;
  const etaS = Math.sqrt(omega * mu / sigma);
  const reflectionRaw = 20 * Math.log10(eta0 / (4 * etaS));
  const reflectionLoss = reflectionRaw < 0 ? 0 : reflectionRaw;
  const a = Math.sqrt(omega * mu / (2 * sigma));
  const nRe = eta0 - a;
  const nIm = -a;
  const dRe = eta0 + a;
  const dIm = a;
  const dMag2 = dRe * dRe + dIm * dIm;
  const gRe = (nRe * dRe + nIm * dIm) / dMag2;
  const gIm = (nIm * dRe - nRe * dIm) / dMag2;
  const g2Re = gRe * gRe - gIm * gIm;
  const g2Im = 2 * gRe * gIm;
  const decay = Math.exp(-2 * x);
  const eRe = decay * Math.cos(2 * x);
  const eIm = -decay * Math.sin(2 * x);
  const pRe = g2Re * eRe - g2Im * eIm;
  const pIm = g2Re * eIm + g2Im * eRe;
  const multipleReflectionLoss = 20 * Math.log10(Math.hypot(1 - pRe, -pIm));
  const totalSE = absorptionLoss + reflectionLoss + multipleReflectionLoss;
  const thicknessVsSkin = t_m / skinDepth_m;
  if (thickness < skinDepth2 * 1e-3) {
    warnings.push("Enclosure thinner than skin depth — poor HF shielding");
  }
  return {
    values: {
      absorptionLoss,
      reflectionLoss,
      totalSE,
      skinDepth: skinDepth2,
      thicknessVsSkin,
      multipleReflectionLoss
    },
    warnings
  };
}
