// src/lib/calculators/rf/waveguide-cutoff.ts
function calculateWaveguideCutoff(inputs) {
  const { width, height, frequency, modeM, modeN } = inputs;
  if (modeM === 0 && modeN === 0) {
    return {
      values: {},
      errors: ["TEM00 mode invalid for rectangular waveguide"]
    };
  }
  const c2 = 299792458;
  const a = width * 1e-3;
  const b = height * 1e-3;
  const cutoffFreq_Hz = c2 / 2 * Math.sqrt(Math.pow(modeM / a, 2) + Math.pow(modeN / b, 2));
  const cutoffFreq = cutoffFreq_Hz / 1e9;
  const f_Hz = frequency * 1e9;
  const warnings = [];
  let guideWavelength = NaN;
  let phaseVelocity = NaN;
  let groupVelocity = NaN;
  let betaPropagates = 0;
  if (f_Hz <= cutoffFreq_Hz) {
    warnings.push(
      "Below cutoff: the mode is evanescent and does not propagate, so it has no guide wavelength, phase velocity or group velocity"
    );
    betaPropagates = 0;
  } else {
    betaPropagates = 1;
    const ratio = cutoffFreq_Hz / f_Hz;
    guideWavelength = c2 / (f_Hz * Math.sqrt(1 - ratio * ratio)) * 1e3;
    phaseVelocity = 1 / Math.sqrt(1 - ratio * ratio);
    groupVelocity = Math.sqrt(1 - ratio * ratio);
  }
  return {
    values: {
      cutoffFreq,
      guideWavelength,
      phaseVelocity,
      groupVelocity,
      betaPropagates
    },
    warnings: warnings.length > 0 ? warnings : void 0
  };
}
