// src/lib/calculators/antenna/_sici.ts
var EULER_GAMMA = 0.5772156649015329;
var SERIES_LIMIT = 2;
var EPS = 1e-17;
var CF_EPS = 1e-16;
var MAX_TERMS = 1e3;
function sici(x) {
  if (!(x >= 0)) return [NaN, NaN];
  if (x === 0) return [0, -Infinity];
  if (!Number.isFinite(x)) return [Math.PI / 2, 0];
  if (x < SERIES_LIMIT) {
    let t = x;
    let si = 0;
    for (let n = 1; n < MAX_TERMS; n += 2) {
      const add = t / n;
      si += add;
      if (Math.abs(add) < EPS * Math.abs(si)) break;
      t *= -x * x / ((n + 1) * (n + 2));
    }
    t = -x * x / 2;
    let sum = 0;
    for (let n = 2; n < MAX_TERMS; n += 2) {
      const add = t / n;
      sum += add;
      if (Math.abs(add) < EPS * Math.max(Math.abs(sum), 1e-300)) break;
      t *= -x * x / ((n + 1) * (n + 2));
    }
    return [si, EULER_GAMMA + Math.log(x) + sum];
  }
  let bRe = 1;
  const bIm = x;
  let cRe = 1e300;
  let cIm = 0;
  let den = bRe * bRe + bIm * bIm;
  let dRe = bRe / den;
  let dIm = -bIm / den;
  let hRe = dRe;
  let hIm = dIm;
  for (let i = 2; i < MAX_TERMS; i++) {
    const a = -(i - 1) * (i - 1);
    bRe += 2;
    const qRe = a * dRe + bRe;
    const qIm = a * dIm + bIm;
    den = qRe * qRe + qIm * qIm;
    dRe = qRe / den;
    dIm = -qIm / den;
    den = cRe * cRe + cIm * cIm;
    cRe = bRe + a * cRe / den;
    cIm = bIm - a * cIm / den;
    const delRe = cRe * dRe - cIm * dIm;
    const delIm = cRe * dIm + cIm * dRe;
    const nRe = hRe * delRe - hIm * delIm;
    const nIm = hRe * delIm + hIm * delRe;
    hRe = nRe;
    hIm = nIm;
    if (Math.abs(delRe - 1) + Math.abs(delIm) < CF_EPS) break;
  }
  const cs = Math.cos(x);
  const sn = Math.sin(x);
  const re = hRe * cs + hIm * sn;
  const im = hIm * cs - hRe * sn;
  return [Math.PI / 2 + im, -re];
}

