// src/lib/calculators/rf/line-of-sight.ts
var C3 = 299792458;
var EARTH_RADIUS2 = 6371e3;
var LINE_OF_SIGHT_VALIDITY = [
  {
    quantity: "rayGradient",
    max: 5,
    unit: "°",
    label: "Path angle to the horizontal",
    source: "ITU-R P.526-15, §4.4: the small-angle geometry holds for ray gradients up to about 5°"
  },
  {
    quantity: "frequency",
    min: 0.01,
    unit: "GHz",
    label: "Frequency",
    source: "ITU-R P.526-15, §3.2: spherical-Earth method for 10 MHz and above"
  }
];
function calculateLineOfSight(inputs) {
  const { antennaHeight1, antennaHeight2, kFactor, pathLength, pointDistance, frequency, fresnelFraction } = inputs;
  if (!(antennaHeight1 >= 0) || !(antennaHeight2 >= 0)) {
    return { values: {}, errors: ["Antenna heights cannot be negative"] };
  }
  if (!(kFactor > 0)) return { values: {}, errors: ["The k-factor must be greater than 0"] };
  if (!(pathLength > 0)) return { values: {}, errors: ["Path length must be greater than 0"] };
  if (!(pointDistance >= 0 && pointDistance <= pathLength)) {
    return { values: {}, errors: ["The point must lie on the path: between 0 and the path length from antenna 1"] };
  }
  if (!(frequency > 0)) return { values: {}, errors: ["Frequency must be greater than 0"] };
  if (!(fresnelFraction >= 0)) return { values: {}, errors: ["The Fresnel-zone fraction cannot be negative"] };
  const ae = kFactor * EARTH_RADIUS2;
  const d = pathLength * 1e3;
  const d1 = pointDistance * 1e3;
  const d2 = d - d1;
  const lambda = C3 / (frequency * 1e9);
  const horizon1 = Math.sqrt(2 * ae * antennaHeight1);
  const horizon2 = Math.sqrt(2 * ae * antennaHeight2);
  const bulge = d1 * d2 / (2 * ae);
  const fresnelRadius = Math.sqrt(lambda * d1 * d2 / d);
  const requiredClearance = bulge + fresnelFraction * fresnelRadius;
  const rayHeight = (antennaHeight1 * d2 + antennaHeight2 * d1) / d - bulge;
  const maxObstacleHeight = rayHeight - fresnelFraction * fresnelRadius;
  const rayGradient = Math.atan(Math.abs(antennaHeight2 - antennaHeight1) / d) * 180 / Math.PI;
  const warnings = checkValidity(LINE_OF_SIGHT_VALIDITY, { rayGradient, frequency });
  return {
    values: {
      maxLosDistance: (horizon1 + horizon2) / 1e3,
      horizon1: horizon1 / 1e3,
      horizon2: horizon2 / 1e3,
      bulge,
      fresnelRadius,
      requiredClearance,
      rayHeight,
      maxObstacleHeight
    },
    warnings
  };
}
