// src/lib/calculators/rf/directional-coupler.ts
var C0 = 299792458;
function directionalCouplerValidity(couplingLimit) {
  return [
    {
      quantity: "coupling",
      min: couplingLimit,
      unit: "dB",
      label: "Coupling C",
      source: "Pozar, Microwave Engineering, 4th ed. (2012), §7.6, p. 355, and §7.7, p. 359: a single edge-coupled section is impractical at tight coupling, too loose for 3 or 6 dB; the limit is the one entered on this page"
    }
  ];
}
var DIRECTIONAL_COUPLER_VALIDITY = directionalCouplerValidity(8);
function calculateDirectionalCoupler(inputs) {
  const { coupling, z0, frequency, effPermittivity, directivity, couplingLimit } = inputs;
  if (!(coupling > 0)) return { values: {}, errors: ["Coupling must be greater than 0 dB"] };
  if (!(z0 > 0)) return { values: {}, errors: ["System impedance must be greater than 0"] };
  if (!(frequency > 0)) return { values: {}, errors: ["Frequency must be greater than 0"] };
  if (!(effPermittivity >= 1)) return { values: {}, errors: ["Effective permittivity must be at least 1"] };
  if (!(directivity >= 0)) return { values: {}, errors: ["Directivity cannot be negative"] };
  if (!(couplingLimit >= 0)) return { values: {}, errors: ["The coupling limit cannot be negative"] };
  const c2 = 10 ** (-coupling / 20);
  const evenModeImpedance = z0 * Math.sqrt((1 + c2) / (1 - c2));
  const oddModeImpedance = z0 * Math.sqrt((1 - c2) / (1 + c2));
  const throughLoss = -10 * Math.log10(1 - c2 * c2);
  const isolation = coupling + directivity;
  const coupledLength = C0 / (4 * frequency * 1e9 * Math.sqrt(effPermittivity)) * 1e3;
  const warnings = checkValidity(directionalCouplerValidity(couplingLimit), { coupling });
  return {
    values: {
      evenModeImpedance,
      oddModeImpedance,
      couplingFactor: c2,
      throughLoss,
      isolation,
      coupledLength
    },
    warnings
  };
}
