var CIRCULAR_WAVEGUIDE_VALIDITY = [
  {
    quantity: "lossTangent",
    max: 0.1,
    label: "Loss tangent tan δ",
    source: "Pozar, Microwave Engineering, 4th ed. (2012), §3.1, Eq. (3.29), p. 102: the dielectric attenuation assumes small loss, tan δ ≪ 1"
  },
  {
    quantity: "skinDepthRatio",
    max: 0.01,
    label: "Skin depth / radius δs/a",
    source: "Pozar, Microwave Engineering, 4th ed. (2012), §1.4, p. 19, and §3.4, Eq. (3.133), p. 125: the perturbation method assumes a good conductor, δs ≪ a"
  }
];
function calculateCircularWaveguide(inputs) {
  const { radius, permittivity, frequency, modeType, modeN, modeM, conductivity, lossTangent, length } = inputs;
  if (!(radius > 0)) return { values: {}, errors: ["Radius must be greater than 0"] };
  if (!(permittivity >= 1)) return { values: {}, errors: ["Relative permittivity must be at least 1"] };
  if (!(frequency > 0)) return { values: {}, errors: ["Frequency must be greater than 0"] };
  if (!(conductivity > 0)) return { values: {}, errors: ["Wall conductivity must be greater than 0"] };
  if (!(lossTangent >= 0)) return { values: {}, errors: ["Loss tangent cannot be negative"] };
  if (!(length >= 0)) return { values: {}, errors: ["Guide length cannot be negative"] };
  const type = Math.round(modeType);
  const n = Math.round(modeN);
  const m = Math.round(modeM);
  if (type !== 0 && type !== 1) return { values: {}, errors: ["Mode type must be 0 (TE) or 1 (TM)"] };
  if (!(n >= 0 && n <= 5) || !(m >= 1 && m <= 5)) {
    return { values: {}, errors: ["Mode indices must be n = 0 to 5 and m = 1 to 5"] };
  }
  const a = radius * 1e-3;
  const f = frequency * 1e9;
  const sqrtEr = Math.sqrt(permittivity);
  const chi = type === 0 ? TE_ROOTS[n][m - 1] : TM_ROOTS[n][m - 1];
  const cutoff = C5 * chi / (2 * Math.PI * a * sqrtEr);
  const te11Cutoff = C5 * TE_ROOTS[1][0] / (2 * Math.PI * a * sqrtEr);
  const tm01Cutoff = C5 * TM_ROOTS[0][0] / (2 * Math.PI * a * sqrtEr);
  const k = 2 * Math.PI * f * sqrtEr / C5;
  const kc = chi / a;
  const eta = ETA02 / sqrtEr;
  const sigma = conductivity * 1e6;
  const omega = 2 * Math.PI * f;
  const rs = Math.sqrt(omega * MU02 / (2 * sigma));
  const skinDepth2 = Math.sqrt(2 / (omega * MU02 * sigma));
  const warnings = checkValidity(CIRCULAR_WAVEGUIDE_VALIDITY, { lossTangent, skinDepthRatio: skinDepth2 / a });
  const values = {
    cutoffFreq: cutoff / 1e9,
    te11Cutoff: te11Cutoff / 1e9,
    tm01Cutoff: tm01Cutoff / 1e9,
    propagates: 0,
    beta: NaN,
    guideWavelength: NaN,
    phaseVelocity: NaN,
    groupVelocity: NaN,
    waveImpedance: NaN,
    conductorAttenuation: NaN,
    dielectricAttenuation: NaN,
    totalLoss: NaN,
    evanescentAttenuation: NaN
  };
  if (f <= cutoff) {
    values.evanescentAttenuation = Math.sqrt(kc * kc - k * k) * NP_TO_DB;
    warnings.push(
      "Below cutoff: the selected mode does not propagate and decays at the evanescent attenuation shown; its guide wavelength, phase and group velocities, wave impedance and losses are not defined."
    );
    return { values, warnings };
  }
  const beta = Math.sqrt(k * k - kc * kc);
  const x = cutoff / f;
  const root = Math.sqrt(1 - x * x);
  const alphaC = type === 0 ? rs / (a * eta * root) * (x * x + n * n / (chi * chi - n * n)) : rs / (a * eta * root);
  const alphaD = k * k * lossTangent / (2 * beta);
  const phaseVelocity = omega / beta;
  values.propagates = 1;
  values.beta = beta;
  values.guideWavelength = 2 * Math.PI / beta * 1e3;
  values.phaseVelocity = phaseVelocity / C5;
  values.groupVelocity = C5 / (permittivity * phaseVelocity);
  values.waveImpedance = type === 0 ? k * eta / beta : beta * eta / k;
  values.conductorAttenuation = alphaC * NP_TO_DB;
  values.dielectricAttenuation = alphaD * NP_TO_DB;
  values.totalLoss = (alphaC + alphaD) * NP_TO_DB * length;
  return { values, warnings };
}
