// src/lib/calculators/iot/lora-link-budget.ts
var C03 = 299792458;
var KT0_DBM_PER_HZ2 = 10 * Math.log10(1380649e-29 * 290 * 1e3);
var SNR_LIMIT = { 6: -5, 7: -7.5, 8: -10, 9: -12.5, 10: -15, 11: -17.5, 12: -20 };
var DATASHEET = "Semtech SX1276/77/78/79 datasheet, Rev. 4 (2015), Table 1";
var HATA = "Hata, IEEE Trans. Veh. Technol. VT-29(3), 1980, as given in 3GPP TR 43.030 V18.0.0, Annex B.1 and §3.4.1";
var MODEL_NAMES = [
  "free space",
  "Okumura–Hata, urban (small/medium city)",
  "Okumura–Hata, urban (large city)",
  "Okumura–Hata, suburban",
  "Okumura–Hata, rural quasi-open",
  "Okumura–Hata, rural open"
];
function loraValidity(model) {
  const bounds = [
    { quantity: "bandwidth", min: 7.8, max: 500, unit: "kHz", label: "Bandwidth BW", source: DATASHEET },
    { quantity: "frequency", min: 137, max: 1020, unit: "MHz", label: "Frequency", source: `${DATASHEET}, the SX1276's frequency range` }
  ];
  if (model >= 1) {
    bounds.push(
      { quantity: "frequency", min: 150, max: 1500, unit: "MHz", label: "Frequency for Okumura–Hata", source: HATA },
      { quantity: "distance", min: 1, max: 20, unit: "km", label: "Distance for Okumura–Hata", source: HATA },
      { quantity: "baseHeight", min: 30, max: 200, unit: "m", label: "Base-station height h_b", source: HATA },
      { quantity: "mobileHeight", min: 1, max: 10, unit: "m", label: "Mobile height h_m", source: HATA },
      { quantity: "maxRange", min: 1, max: 20, unit: "km", label: "Maximum range by Okumura–Hata", source: HATA }
    );
  }
  return bounds;
}
var LORA_VALIDITY = loraValidity(1);
function hataPathLoss(model, fMHz, dKm, hb, hm) {
  const lf = Math.log10(fMHz);
  let a = (1.1 * lf - 0.7) * hm - (1.56 * lf - 0.8);
  if (model === 2) {
    a = fMHz <= 200 ? 8.29 * Math.log10(1.54 * hm) ** 2 - 1.1 : 3.2 * Math.log10(11.75 * hm) ** 2 - 4.97;
  }
  const urban = 69.55 + 26.16 * lf - 13.82 * Math.log10(hb) - a + (44.9 - 6.55 * Math.log10(hb)) * Math.log10(dKm);
  if (model === 3) return urban - 2 * Math.log10(fMHz / 28) ** 2 - 5.4;
  if (model === 4) return urban - 4.78 * lf ** 2 + 18.33 * lf - 35.94;
  if (model === 5) return urban - 4.78 * lf ** 2 + 18.33 * lf - 40.94;
  return urban;
}
function calculateLora(inputs) {
  const sf = Math.round(inputs.spreadingFactor);
  const cr = Math.round(inputs.codingRate);
  const ih = Math.round(inputs.implicitHeader);
  const crc = Math.round(inputs.crc);
  const model = Math.round(inputs.pathLossModel);
  const pl = Math.round(inputs.payloadLength);
  const {
    bandwidth,
    preambleLength,
    noiseFigure,
    txPower,
    txGain,
    rxGain,
    losses,
    frequency,
    distance,
    baseHeight,
    mobileHeight,
    dutyCycle
  } = inputs;
  if (!(sf >= 6 && sf <= 12)) return { values: {}, errors: ["Spreading factor must be 6 to 12 (SX1276/77/78/79 datasheet, Table 13)"] };
  if (!(bandwidth > 0)) return { values: {}, errors: ["Bandwidth must be greater than 0"] };
  if (!(cr >= 1 && cr <= 4)) return { values: {}, errors: ["Coding rate must be 1 to 4, for 4/5 to 4/8"] };
  if (!(pl >= 1 && pl <= 255)) return { values: {}, errors: ["Payload length must be 1 to 255 bytes"] };
  if (!(preambleLength >= 0)) return { values: {}, errors: ["Preamble length cannot be negative"] };
  if (ih !== 0 && ih !== 1) return { values: {}, errors: ["Header mode must be 0 (explicit) or 1 (implicit)"] };
  if (crc !== 0 && crc !== 1) return { values: {}, errors: ["CRC must be 1 (on) or 0 (off)"] };
  if (!(noiseFigure >= 0)) return { values: {}, errors: ["Noise figure cannot be negative"] };
  if (!(frequency > 0)) return { values: {}, errors: ["Frequency must be greater than 0"] };
  if (!(model >= 0 && model <= 5)) return { values: {}, errors: ["Path-loss model must be 0 (free space) or 1 to 5 (Okumura–Hata)"] };
  if (!(distance > 0)) return { values: {}, errors: ["Distance must be greater than 0"] };
  if (!(baseHeight > 0)) return { values: {}, errors: ["Base-station height must be greater than 0"] };
  if (!(mobileHeight > 0)) return { values: {}, errors: ["Mobile height must be greater than 0"] };
  if (!(dutyCycle > 0 && dutyCycle <= 100)) return { values: {}, errors: ["Duty cycle must be greater than 0 and at most 100%"] };
  const warnings = [];
  const bwHz = bandwidth * 1e3;
  const sensitivity = KT0_DBM_PER_HZ2 + 10 * Math.log10(bwHz) + noiseFigure + SNR_LIMIT[sf];
  const symbolTime = 2 ** sf / bwHz * 1e3;
  const de = symbolTime > 16 ? 1 : 0;
  const payloadSymbols = 8 + Math.max(
    Math.ceil((8 * pl - 4 * sf + 28 + 16 * crc - 20 * ih) / (4 * (sf - 2 * de))) * (cr + 4),
    0
  );
  const timeOnAir = (preambleLength + 4.25) * symbolTime + payloadSymbols * symbolTime;
  const bitRate = sf * (4 / (4 + cr)) * bwHz / 2 ** sf;
  const offTime = timeOnAir / 1e3 * (100 / dutyCycle - 1);
  const packetsPerHour = 3600 * (dutyCycle / 100) / (timeOnAir / 1e3);
  if (sf === 6 && ih === 0) {
    warnings.push(
      "The SX1276 runs SF6 only with an implicit header (datasheet §4.1.1.2); the time on air is given for the explicit header entered."
    );
  }
  const fHz = frequency * 1e6;
  let pathLoss;
  let maxRange;
  const eirpAndGains = txPower + txGain + rxGain - losses;
  const maxPathLoss = eirpAndGains - sensitivity;
  if (model === 0) {
    pathLoss = 20 * Math.log10(4 * Math.PI * distance * 1e3 * fHz / C03);
    maxRange = C03 / (4 * Math.PI * fHz) * 10 ** (maxPathLoss / 20) / 1e3;
  } else {
    pathLoss = hataPathLoss(model, frequency, distance, baseHeight, mobileHeight);
    const at1km = hataPathLoss(model, frequency, 1, baseHeight, mobileHeight);
    maxRange = 10 ** ((maxPathLoss - at1km) / (44.9 - 6.55 * Math.log10(baseHeight)));
    if (model === 2 && frequency > 200 && frequency < 400) {
      warnings.push(
        "Okumura–Hata gives the large-city height correction only up to 200 MHz and from 400 MHz (3GPP TR 43.030 Annex B.1); between them the 400 MHz form is used."
      );
    }
  }
  const receivedPower = eirpAndGains - pathLoss;
  const linkMargin2 = receivedPower - sensitivity;
  warnings.push(...checkValidity(loraValidity(model), {
    bandwidth,
    frequency,
    distance,
    baseHeight,
    mobileHeight,
    maxRange
  }));
  return {
    values: {
      linkMargin: linkMargin2,
      sensitivity,
      receivedPower,
      pathLoss,
      maxRange,
      timeOnAir,
      symbolTime,
      payloadSymbols,
      lowDataRateOptimize: de,
      bitRate,
      offTime,
      packetsPerHour
    },
    warnings
  };
}
