// src/lib/calculators/rf/microstrip-mitered-bend.ts
var DOUVILLE_JAMES = "Douville & James, IEEE Trans. MTT-26(3), pp. 175–181 (1978)";
var MITERED_BEND_VALIDITY = [
  {
    quantity: "widthToHeight",
    min: 0.25,
    label: "Width-to-height ratio W/h",
    source: `${DOUVILLE_JAMES}: the optimum-mitre relation holds for W/h ≥ 0.25 (measured from 0.25 to 2.75)`
  },
  {
    quantity: "permittivity",
    max: 25,
    label: "Relative permittivity εr",
    source: `${DOUVILLE_JAMES}: the optimum-mitre relation holds for εr ≤ 25 (measured from 2.5 to 25)`
  }
];
function calculateMiteredBend(inputs) {
  const { width, height, permittivity } = inputs;
  if (!(width > 0)) return { values: {}, errors: ["Strip width must be greater than 0"] };
  if (!(height > 0)) return { values: {}, errors: ["Substrate height must be greater than 0"] };
  if (!(permittivity >= 1)) return { values: {}, errors: ["Relative permittivity must be at least 1"] };
  const widthToHeight = width / height;
  const mitrePercent = 52 + 65 * Math.exp(-1.35 * widthToHeight);
  if (!(mitrePercent < 100)) {
    return {
      values: {},
      errors: ["The strip is too narrow for the relation: below W/h of about 0.225 the optimum mitre would exceed 100% and the cut would sever the line"]
    };
  }
  const diagonal = width * Math.SQRT2;
  const mitreDepth = mitrePercent / 100 * diagonal;
  const chamferLength = mitreDepth * Math.SQRT2;
  const remainingDiagonal = diagonal - mitreDepth;
  const warnings = checkValidity(MITERED_BEND_VALIDITY, { widthToHeight, permittivity });
  return {
    values: { widthToHeight, mitrePercent, diagonal, mitreDepth, chamferLength, remainingDiagonal },
    warnings
  };
}
