// src/lib/calculators/power/rc-snubber.ts
var TODD = "Todd, Snubber Circuits: Theory, Design and Application, Unitrode (1993), TI SLUP100";
var SEVERNS = "Severns, Design of Snubbers for Power Circuits, Cornell Dubilier (1999)";
function rcSnubberValidity(minOnTimeNs) {
  return [
    {
      quantity: "capacitorMultiple",
      min: 2,
      max: 4,
      label: "Capacitor multiple n = C_s/C_p",
      source: `${TODD}, p. 2-4: the snubber capacitance is generally two to four times the parasitic capacitance`
    },
    {
      quantity: "timeConstant",
      max: minOnTimeNs / 2,
      unit: "ns",
      label: "Snubber time constant R·C_s",
      source: `${SEVERNS}, p. 15: the capacitor must discharge within the minimum on-time, and two time constants leave 0.14 of the voltage; the on-time is the one entered on this page`
    }
  ];
}
var RC_SNUBBER_VALIDITY = rcSnubberValidity(100);
function calculateRcSnubber(inputs) {
  const { ringFrequency, addedCapacitance, ringFrequencyAdded, capacitorMultiple, switchVoltage, switchingFrequency, minOnTime } = inputs;
  if (!(ringFrequency > 0)) return { values: {}, errors: ["The ring frequency must be greater than 0"] };
  if (!(addedCapacitance > 0)) return { values: {}, errors: ["The added test capacitance must be greater than 0"] };
  if (!(ringFrequencyAdded > 0)) return { values: {}, errors: ["The ring frequency with the capacitor added must be greater than 0"] };
  if (!(ringFrequencyAdded < ringFrequency)) {
    return {
      values: {},
      errors: ["Added capacitance must lower the ring frequency: the frequency measured with the capacitor added (f₁) must be below the original (f₀)"]
    };
  }
  if (!(capacitorMultiple > 0)) return { values: {}, errors: ["The capacitor multiple must be greater than 0"] };
  if (!(switchVoltage > 0)) return { values: {}, errors: ["The switched voltage must be greater than 0"] };
  if (!(switchingFrequency > 0)) return { values: {}, errors: ["The switching frequency must be greater than 0"] };
  if (!(minOnTime > 0)) return { values: {}, errors: ["The minimum on-time must be greater than 0"] };
  const ratio = (ringFrequency / ringFrequencyAdded) ** 2;
  const parasiticCapacitance = addedCapacitance / (ratio - 1);
  const cp = parasiticCapacitance * 1e-12;
  const lp = 1 / ((2 * Math.PI * ringFrequency * 1e6) ** 2 * cp);
  const characteristicImpedance = Math.sqrt(lp / cp);
  const snubberResistance = characteristicImpedance;
  const snubberCapacitance = capacitorMultiple * parasiticCapacitance;
  const resistorPower = snubberCapacitance * 1e-12 * switchVoltage ** 2 * switchingFrequency * 1e3;
  const timeConstant = snubberResistance * snubberCapacitance * 1e-3;
  const warnings = checkValidity(rcSnubberValidity(minOnTime), { capacitorMultiple, timeConstant });
  return {
    values: {
      snubberResistance,
      snubberCapacitance,
      resistorPower,
      parasiticCapacitance,
      parasiticInductance: lp * 1e9,
      characteristicImpedance,
      timeConstant
    },
    warnings
  };
}
function fmt(value, units) {
  for (const [scale2, unit2] of units) {
    if (value >= scale2) return `${+(value / scale2).toPrecision(3)} ${unit2}`;
  }
  const [scale, unit] = units[units.length - 1];
  return `${+(value / scale).toPrecision(3)} ${unit}`;
}
