// src/lib/calculators/general/555-timer.ts
function calculate555Timer(inputs) {
  const { mode, ra, rb, c: c2, vcc } = inputs;
  const ra_Ohm = Math.max(ra, 1e-3) * 1e3;
  const rb_Ohm = Math.max(rb, 1e-3) * 1e3;
  const c_F = Math.max(c2, 1e-4) * 1e-6;
  let frequency;
  let period;
  let pulseWidth;
  let dutyCycle;
  let highTime;
  let lowTime;
  if (mode >= 1) {
    pulseWidth = Math.log(3) * ra_Ohm * c_F * 1e3;
    highTime = pulseWidth;
    lowTime = 0;
    period = 0;
    frequency = 0;
    dutyCycle = 0;
  } else {
    highTime = Math.LN2 * (ra_Ohm + rb_Ohm) * c_F * 1e3;
    lowTime = Math.LN2 * rb_Ohm * c_F * 1e3;
    period = highTime + lowTime;
    frequency = period > 0 ? 1e3 / period : 0;
    dutyCycle = period > 0 ? highTime / period * 100 : 0;
    pulseWidth = highTime;
  }
  return {
    values: {
      frequency,
      period,
      pulseWidth,
      dutyCycle,
      highTime,
      lowTime
    }
  };
}
