// src/lib/calculators/motor/torque-unit-converter.ts
function calculateTorqueUnitConverter(inputs) {
  const { nm } = inputs;
  const LBF_FT_IN_NM2 = 0.45359237 * 9.80665 * 0.3048;
  const lbFt = nm / LBF_FT_IN_NM2;
  const lbIn = nm * 12 / LBF_FT_IN_NM2;
  const ozIn = nm * 192 / LBF_FT_IN_NM2;
  const kgCm = nm * 100 / 9.80665;
  const kgM = nm / 9.80665;
  const dyneCm = nm * 1e7;
  return { values: { lbFt, lbIn, ozIn, kgCm, kgM, dyneCm } };
}
