// src/lib/calculators/signal/ber-snr.ts
function erfc(x) {
  if (x < 0) return 2 - erfc(-x);
  if (x === 0) return 1;
  if (x > 27) return 0;
  if (x < 0.5) {
    const x2 = x * x;
    let term = 1;
    let sum = 1;
    for (let n = 1; n <= 50; n++) {
      term *= -x2 / n;
      sum += term / (2 * n + 1);
      if (Math.abs(term / (2 * n + 1)) < 1e-17) break;
    }
    return 1 - 2 / Math.sqrt(Math.PI) * x * sum;
  }
  const N = 200;
  let f = 0;
  for (let n = N; n >= 2; n--) {
    f = (n - 1) / 2 / (x + f);
  }
  f = 1 / (x + f);
  return Math.exp(-x * x) / Math.sqrt(Math.PI) * f;
}
function calculateBerSnr(inputs) {
  const { ebN0dB, modulation } = inputs;
  const ebN0 = Math.pow(10, ebN0dB / 10);
  const modCode = Math.round(modulation);
  let ber;
  let bitsPerSymbol;
  switch (modCode) {
    case 1:
      ber = 0.5 * erfc(Math.sqrt(ebN0));
      bitsPerSymbol = 1;
      break;
    case 2:
      ber = 0.5 * erfc(Math.sqrt(ebN0));
      bitsPerSymbol = 2;
      break;
    case 3:
      {
        const sinPi8 = Math.sin(Math.PI / 8);
        ber = 1 / 3 * erfc(Math.sqrt(ebN0 * 3 * sinPi8 * sinPi8));
        bitsPerSymbol = 3;
      }
      break;
    case 4:
      ber = 0.375 * erfc(Math.sqrt(ebN0 * 2 / 5));
      bitsPerSymbol = 4;
      break;
    default:
      ber = 0.5 * erfc(Math.sqrt(ebN0));
      bitsPerSymbol = 1;
  }
  const berClamped = Math.max(ber, 1e-12);
  const berLog10 = Math.log10(berClamped);
  return {
    values: {
      ber: berClamped,
      berLog10,
      bitsPerSymbol
    }
  };
}
