// src/lib/calculators/general/delta-wye-conversion.ts
function calculateDeltaWye(inputs) {
  const { ra, rb, rc, conversionDir } = inputs;
  if (ra <= 0 || rb <= 0 || rc <= 0) {
    return { values: {}, errors: ["All resistor values must be greater than 0"] };
  }
  let r1, r2, r3;
  let rdA, rdB, rdC;
  if (conversionDir === 0) {
    const rSum = ra + rb + rc;
    r1 = rb * rc / rSum;
    r2 = ra * rc / rSum;
    r3 = ra * rb / rSum;
    rdA = ra;
    rdB = rb;
    rdC = rc;
  } else {
    const r1w = ra;
    const r2w = rb;
    const r3w = rc;
    const numerator = r1w * r2w + r2w * r3w + r3w * r1w;
    rdA = numerator / r1w;
    rdB = numerator / r2w;
    rdC = numerator / r3w;
    r1 = r1w;
    r2 = r2w;
    r3 = r3w;
  }
  return {
    values: {
      r1,
      r2,
      r3,
      rdA,
      rdB,
      rdC
    }
  };
}
