// src/lib/calculators/pcb/asymmetric-stripline.ts
var C_MM_PER_PS2 = 0.299792458;
var OFFSET_FIT = { minWb: 0.05, maxWb: 1.2, minNearFraction: 0.05 };
function outsideOffsetFit(w, h1, h2) {
  const b = h1 + h2;
  if (!(b > 0)) return false;
  const near = Math.min(h1, h2) / b;
  if (!(near < 0.5)) return false;
  const wb = w / b;
  return wb < OFFSET_FIT.minWb || wb > OFFSET_FIT.maxWb || near < OFFSET_FIT.minNearFraction;
}
function calculateAsymmetricStripline(inputs) {
  const { traceWidth, heightToNearPlane, heightToFarPlane, copperThickness, dielectricConst } = inputs;
  const warnings = [];
  const t = copperThickness / 1e3;
  const h1 = heightToNearPlane;
  const h2 = heightToFarPlane;
  const planeSpacing = h1 + h2 + t;
  const { Z0: impedance } = asymmetricStripline(traceWidth, h1, h2, dielectricConst, t);
  const { Z0: centredImpedance } = symmetricStripline(
    traceWidth,
    planeSpacing,
    dielectricConst,
    t
  );
  const propagationDelay = Math.sqrt(dielectricConst) / C_MM_PER_PS2;
  const asymmetryRatio = h2 / h1;
  const offsetPenalty = centredImpedance > 0 ? (impedance - centredImpedance) / centredImpedance * 100 : 0;
  if (h2 < h1) {
    warnings.push("Far-plane height is smaller than near-plane height — swap the two values");
  }
  if (outsideOffsetFit(traceWidth, h1, h2)) {
    warnings.push(
      "Outside the range the off-centre correction was fitted over (W/b 0.05–1.2 and a near-plane gap of at least 0.05 of b = h₁ + h₂, about a 19:1 offset) — Z₀ is extrapolated and may be off by more than the model’s 0.75%"
    );
  }
  if (t / planeSpacing > 0.25) {
    warnings.push("t/b > 0.25 — copper is thick relative to the plane spacing; Z₀ is approximate");
  }
  if (asymmetryRatio > 3) {
    warnings.push(
      "Strongly offset trace — it couples almost entirely to the near plane, so keep that plane unbroken beneath the route"
    );
  }
  return {
    values: {
      impedance,
      centredImpedance,
      offsetPenalty,
      propagationDelay,
      planeSpacing,
      asymmetryRatio
    },
    warnings: warnings.length > 0 ? warnings : void 0
  };
}
