// src/lib/calculators/pcb/bga-breakout-width.ts
function calculateBgaBreakoutWidth(inputs) {
  const { ballPitch, landDiameter, minClearance, tracesPerChannel, diagonalRoute } = inputs;
  if (ballPitch <= 0 || landDiameter <= 0 || minClearance <= 0) {
    return {
      values: {},
      errors: ["Ball pitch, land diameter and minimum clearance must all be greater than zero"]
    };
  }
  const traces = Math.round(tracesPerChannel);
  if (traces < 1) {
    return { values: {}, errors: ["At least one trace must be routed per channel"] };
  }
  const effectivePitch = diagonalRoute >= 0.5 ? ballPitch * Math.SQRT2 : ballPitch;
  const channel = effectivePitch - landDiameter;
  if (channel <= 0) {
    return {
      values: {
        fits: 0,
        channelWidth: 0,
        maxTraceWidth: 0,
        clearanceDemand: 0,
        effectivePitch,
        escapeRows: 0
      },
      errors: [
        `A ${landDiameter} mm land on a ${effectivePitch.toFixed(3)} mm effective pitch leaves no channel — the lands touch. Reduce the land diameter.`
      ]
    };
  }
  const clearanceDemand = (traces + 1) * minClearance;
  const usable = channel - clearanceDemand;
  if (usable <= 0) {
    return {
      values: {
        fits: 0,
        channelWidth: channel,
        maxTraceWidth: 0,
        clearanceDemand,
        effectivePitch,
        escapeRows: 0
      },
      errors: [
        `Routing ${traces} trace${traces > 1 ? "s" : ""} needs ${clearanceDemand.toFixed(3)} mm of clearance but the channel is only ${channel.toFixed(3)} mm. Nothing escapes here — the binding constraint is clearance, and the usual answer is dog-bone fanout to a lower layer.`
      ]
    };
  }
  const maxTraceWidth = usable / traces;
  const escapeRows = traces;
  const warnings = [];
  if (maxTraceWidth < 0.075) {
    warnings.push(
      `A ${maxTraceWidth.toFixed(4)} mm trace is beyond standard fabrication; this geometry needs an advanced process or fewer traces per channel`
    );
  } else if (maxTraceWidth < 0.1) {
    warnings.push(
      `A ${maxTraceWidth.toFixed(4)} mm trace is below the 0.1 mm most shops quote as standard — expect a surcharge`
    );
  }
  if (diagonalRoute >= 0.5) {
    warnings.push("Diagonal escape assumed: the channel is the √2 gap between lands set one pitch apart on each axis");
  }
  return {
    values: {
      maxTraceWidth,
      channelWidth: channel,
      clearanceDemand,
      effectivePitch,
      escapeRows,
      fits: 1
    },
    warnings: warnings.length > 0 ? warnings : void 0
  };
}
