var E12_BASE_VALUES = [1, 1.2, 1.5, 1.8, 2.2, 2.7, 3.3, 3.9, 4.7, 5.6, 6.8, 8.2];
function formatResistorValue(base, mult) {
  const value = Number((base * mult).toPrecision(3));
  if (value >= 1e6) return `${Number((value / 1e6).toPrecision(3))}M`;
  if (value >= 1e3) return `${Number((value / 1e3).toPrecision(3))}k`;
  return `${value}`;
}
function formatCapacitorValue(pF) {
  const value = Number(pF.toPrecision(3));
  if (value >= 1e6) return `${Number((value / 1e6).toPrecision(3))} uF`;
  if (value >= 1e3) return `${Number((value / 1e3).toPrecision(3))} nF`;
  return `${value} pF`;
}
function generateE24Data() {
  const data = [];
  const decades = [1, 10, 100, 1e3, 1e4, 1e5, 1e6];
  for (const base of E24_BASE_VALUES) {
    const row = {
      baseValue: base
    };
    for (const decade of decades) {
      const value = base * decade;
      row[`d${decade}`] = formatResistorValue(base, decade);
      row[`raw${decade}`] = value;
    }
    data.push(row);
  }
  return data;
}
function generateE96Data() {
  const data = [];
  const decades = [1, 10, 100, 1e3, 1e4, 1e5, 1e6];
  for (const base of E96_BASE_VALUES) {
    const row = {
      baseValue: base.toFixed(2)
    };
    for (const decade of decades) {
      const value = base * decade;
      row[`d${decade}`] = formatResistorValue(base, decade);
      row[`raw${decade}`] = value;
    }
    data.push(row);
  }
  return data;
}
function generateCapacitorData() {
  const data = [];
  const capacitorDecades = [1, 10, 100, 1e3, 1e4, 1e5, 1e6];
  for (const base of E12_BASE_VALUES) {
    const isE24Only = !E12_BASE_VALUES.includes(base);
    const row = {
      baseValue: base,
      series: isE24Only ? "E24" : "E12/E24"
    };
    for (const decade of capacitorDecades) {
      const valuePf = base * decade;
      row[`d${decade}`] = formatCapacitorValue(valuePf);
      row[`raw${decade}`] = valuePf;
    }
    data.push(row);
  }
  return data;
}
